export type RenderFn = (
  g: d3.Selection<SVGGElement, unknown, null, undefined>,
  params: Record<string, number | string>,
  meta: ComponentDef,
  graph: ComputationGraph
) => { width: number; height: number };

export interface StepInfo {
  id: number;
  label: string;
  shortLabel: string;
  formula: string;
  explanation: string;
  code: { title: string; lines: string[] };
  svgGroup: string;
  color: string;
  fill: string;
}

export type RichRenderFn = (
  g: d3.Selection<SVGGElement, unknown, null, undefined>,
  params: Record<string, number | string>,
  meta: ComponentDef,
  graph: ComputationGraph
) => { width: number; height: number; steps: StepInfo[] };

