export function hasRichRenderer(id: string): boolean {
  return id in richLoaders;
}

export async function loadRichRenderer(id: string): Promise<RichRenderFn> {
  const loader = richLoaders[id];
  if (loader) return loader();
  throw new Error(`No rich renderer for ${id}`);
}

// Keep these for backward compatibility with any code still using them
export function hasDetailedRenderer(id: string): boolean {
  return id in richLoaders;
}

export async function loadDetailedRenderer(id: string): Promise<RenderFn> {
  const loader = richLoaders[id];
  if (loader) return loader() as unknown as Promise<RenderFn>;
  const generic = await import('./generic');
  return generic.renderGenericDetailed;
}

