import { GraphBuilder } from '../graph/builder';
import { ComponentDef } from './types';

export const diffusionSchedulerComponent: ComponentDef = {
  id: 'diffusion-scheduler',
  name: 'Diffusion Scheduler',
  description: 'Iteratively denoise latents using a learned model and a noise schedule.',
  category: 'multimodal',
  params: [
    { name: 'n_patches', label: 'Latent patches', type: 'number', default: 256, min: 1, max: 1024, step: 1 },
    { name: 'd_model', label: 'Model dimension', type: 'number', default: 768, min: 64, max: 4096, step: 64 },
    { name: 'steps', label: 'Timesteps', type: 'number', default: 50, min: 1, max: 1000, step: 1 }
  ],
  buildGraph: (params) => {
    const n_patches = Number(params.n_patches);
    const d_model = Number(params.d_model);
    const steps = Number(params.steps);

    const g = new GraphBuilder();
    g.input('noise', [n_patches, d_model]);
    g.input('timestep', [1]);

    g.linear('patch_embed', 'noise', [d_model, d_model]);
    g.add('cond', 'patch_embed', 'timestep');
    g.scale('schedule', 'cond', `β_t schedule (${steps})`);
    g.linear('pred', 'schedule', [d_model, d_model]);
    g.output('out', 'pred');
    return g.build();
  }
};
